 <div class="modal" id="craftModal"><div class="modal-card"><div class="modal-head"><div><div class="eyebrow">Make camp</div><h3>What will you make?</h3></div><button class="close" data-close="craftModal">×</button></div><div class="recipe"><div><strong>Lean-to wall</strong><p>3 wood · 2 fiber — shelter from the night</p></div><button data-build="wall">Build</button></div><div class="recipe"><div><strong>Bed of boughs</strong><p>4 fiber · 2 wood — rest & recover</p></div><button data-build="bed">Build</button></div><div class="recipe"><div><strong>Campfire</strong><p>3 wood · 2 stone — warmth after dusk</p></div><button data-build="fire">Build</button></div><div class="recipe"><div><strong>Shared meal</strong><p>3 berries — restore hunger</p></div><button data-build="meal">Eat</button></div><div class="recipe"><div><strong>Drink from stream</strong><p>Be near fresh water</p></div><button data-build="drink">Drink</button></div></div></div>
 <div class="modal" id="bagModal"><div class="modal-card"><div class="modal-head"><div><div class="eyebrow">Your pack</div><h3>Gathered so far</h3></div><button class="close" data-close="bagModal">×</button></div><div class="inventory"><div class="inv-item">Wild berries <b id="invBerries">0</b></div><div class="inv-item">Fallen wood <b id="invWood">0</b></div><div class="inv-item">River stone <b id="invStone">0</b></div><div class="inv-item">Forest fiber <b id="invFiber">0</b></div></div><div class="recipe" style="margin-top:12px"><div><strong>Places you've made</strong><p id="builtList">A place to begin</p></div></div></div></div>
 <script type="module">
 import * as THREE from 'https://cdn.jsdelivr.net/npm/three@0.160.0/build/three.module.js';
-</script>
+
+const $=id=>document.getElementById(id), game=$('game');
+const scene=new THREE.Scene(); scene.background=new THREE.Color(0x9cae9a); scene.fog=new THREE.FogExp2(0x9cae9a,.012);
+const camera=new THREE.PerspectiveCamera(58,innerWidth/innerHeight,.1,180);
+const renderer=new THREE.WebGLRenderer({antialias:true,alpha:false}); renderer.setPixelRatio(Math.min(devicePixelRatio,1.65)); renderer.setSize(innerWidth,innerHeight); renderer.shadowMap.enabled=true; renderer.shadowMap.type=THREE.PCFSoftShadowMap; renderer.outputColorSpace=THREE.SRGBColorSpace; renderer.toneMapping=THREE.ACESFilmicToneMapping; renderer.toneMappingExposure=1.12; game.appendChild(renderer.domElement);
+scene.add(new THREE.HemisphereLight(0xdce9d3,0x263c2c,2.1));
+const sun=new THREE.DirectionalLight(0xffdfaa,2.2); sun.position.set(-25,38,18); sun.castShadow=true; sun.shadow.mapSize.set(1024,1024); sun.shadow.camera.left=-55; sun.shadow.camera.right=55; sun.shadow.camera.top=55; sun.shadow.camera.bottom=-55; scene.add(sun);
+const mat=(color,rough=.88)=>new THREE.MeshStandardMaterial({color,roughness:rough});
+const groundMat=mat(0x52694b), trunkMat=mat(0x574333), leafMats=[mat(0x385941),mat(0x45684b),mat(0x557252),mat(0x304b3d)], rockMat=mat(0x777b69), berryMat=mat(0xc7664f,.55), woodMat=mat(0x98734a), fiberMat=mat(0xb9a777), stoneMat=mat(0xa6a18b), waterMat=new THREE.MeshStandardMaterial({color:0x5c9b9b,roughness:.22,metalness:.1,transparent:true,opacity:.8});
+const ground=new THREE.Mesh(new THREE.CircleGeometry(83,80),groundMat); ground.rotation.x=-Math.PI/2; ground.receiveShadow=true; ground.position.y=-.12; scene.add(ground);
+// Mossy clearings and a curving stream give the forest a readable landmark.
+const water=new THREE.Mesh(new THREE.PlaneGeometry(17,130),waterMat); water.rotation.x=-Math.PI/2; water.position.set(17,-.03,-4); scene.add(water);
+const bankMat=mat(0x9b9873); for(const x of [8.2,25.8]){const bank=new THREE.Mesh(new THREE.PlaneGeometry(1.7,130),bankMat);bank.rotation.x=-Math.PI/2;bank.position.set(x,-.06,-4);scene.add(bank)}
+const clearing=new THREE.Mesh(new THREE.CircleGeometry(9,40),mat(0x6d7950)); clearing.rotation.x=-Math.PI/2; clearing.position.set(-1,-.105,1); clearing.receiveShadow=true; scene.add(clearing);
+// Build a few layered, stylized trees from low-poly primitives.
+const trees=[];
+function makeTree(x,z,scale=1){const group=new THREE.Group();group.position.set(x,0,z);group.scale.setScalar(scale);const trunk=new THREE.Mesh(new THREE.CylinderGeometry(.24,.48,4.2,7),trunkMat);trunk.position.y=2.1;trunk.castShadow=true;group.add(trunk);for(let i=0;i<3;i++){const crown=new THREE.Mesh(new THREE.ConeGeometry(2.45-i*.35,4.5,7),leafMats[(Math.random()*leafMats.length)|0]);crown.position.y=4.2+i*1.35;crown.castShadow=true;group.add(crown)}scene.add(group);trees.push({x,z,r:1.05*scale})}
+for(let i=0;i<84;i++){let a=Math.random()*Math.PI*2,r=14+Math.random()*54,x=Math.cos(a)*r,z=Math.sin(a)*r;if(x>8&&x<26) x=x<17?7:27;if(Math.abs(x)<8&&Math.abs(z)<12)continue;makeTree(x,z,.72+Math.random()*.75)}
+for(let i=0;i<100;i++){let x=(Math.random()-.5)*140,z=(Math.random()-.5)*135;if((x>8&&x<26)|| (Math.abs(x)<9&&Math.abs(z)<12))continue;const b=new THREE.Mesh(new THREE.SphereGeometry(.15+Math.random()*.32,5,4),i%3?leafMats[1]:mat(0x829166));b.scale.y=.5;b.position.set(x,.12,z);scene.add(b)}
+// Simple player silhouette with a small pack.
+const player=new THREE.Group(); const body=new THREE.Mesh(new THREE.CapsuleGeometry(.43,.75,4,8),mat(0x6f7860));body.position.y=1.02;body.castShadow=true;player.add(body);const head=new THREE.Mesh(new THREE.SphereGeometry(.26,10,8),mat(0xc49b78));head.position.y=1.78;head.castShadow=true;player.add(head);const pack=new THREE.Mesh(new THREE.BoxGeometry(.48,.52,.25),mat(0x6d4f37));pack.position.set(0,1.08,.38);pack.castShadow=true;player.add(pack);scene.add(player);player.position.set(-1,0,3);
+// Resource nodes are intentionally visible and distributed around the clearing.
+const nodes=[];let nodeId=0;
+function addNode(kind,x,z){const g=new THREE.Group();g.position.set(x,.12,z);let mesh;if(kind==='berry'){mesh=new THREE.Mesh(new THREE.SphereGeometry(.48,8,7),leafMats[1]);mesh.scale.set(1,.65,.85);g.add(mesh);for(let i=0;i<4;i++){const b=new THREE.Mesh(new THREE.SphereGeometry(.09,7,5),berryMat);b.position.set((Math.random()-.5)*.45,.18+Math.random()*.22,(Math.random()-.5)*.4);g.add(b)}}else if(kind==='wood'){mesh=new THREE.Mesh(new THREE.CylinderGeometry(.12,.16,1.55,7),woodMat);mesh.rotation.z=1.28;mesh.position.y=.12;g.add(mesh);const twig=new THREE.Mesh(new THREE.CylinderGeometry(.045,.07,.55,5),woodMat);twig.position.set(.32,.23,.04);twig.rotation.z=.55;g.add(twig)}else if(kind==='stone'){mesh=new THREE.Mesh(new THREE.DodecahedronGeometry(.42,0),stoneMat);mesh.scale.set(1,.68,.8);g.add(mesh)}else{mesh=new THREE.Mesh(new THREE.ConeGeometry(.32,.8,5),fiberMat);mesh.position.y=.35;g.add(mesh);const leaf=new THREE.Mesh(new THREE.ConeGeometry(.28,.65,5),leafMats[2]);leaf.rotation.z=1.2;leaf.position.set(.18,.24,0);g.add(leaf)}g.traverse(o=>{if(o.isMesh)o.castShadow=true});scene.add(g);const halo=new THREE.Mesh(new THREE.RingGeometry(.48,.53,24),new THREE.MeshBasicMaterial({color:0xd9c38b,transparent:true,opacity:.4,side:THREE.DoubleSide}));halo.rotation.x=-Math.PI/2;halo.position.y=.025;g.add(halo);nodes.push({id:nodeId++,kind,x,z,obj:g,active:true,halo})}
+for(const [kind,count,min,max] of [['berry',19,7,25],['wood',23,6,36],['stone',16,8,40],['fiber',20,7,31]])for(let i=0;i<count;i++){let x,z,tries=0;do{x=(Math.random()-.5)*70;z=(Math.random()-.5)*65;tries++}while((Math.hypot(x+1,z-3)<8||x>9&&x<25||Math.hypot(x,z)<min)&&tries<40);addNode(kind,x,z)}
+// Neighbors are individuals, not a monolith: this forest is shared, and trust is earned.
+function makeNeighbor(name,role,color,x,z,temper){const g=new THREE.Group(),robe=new THREE.Mesh(new THREE.CapsuleGeometry(.42,.8,4,7),mat(color));robe.position.y=1;robe.castShadow=true;g.add(robe);const face=new THREE.Mesh(new THREE.SphereGeometry(.25,9,7),mat(0xb78d6c));face.position.y=1.75;g.add(face);const hair=new THREE.Mesh(new THREE.SphereGeometry(.28,8,6),mat(0x342d25));hair.scale.set(1,.55,1);hair.position.y=1.92;g.add(hair);const marker=new THREE.Mesh(new THREE.OctahedronGeometry(.12),new THREE.MeshBasicMaterial({color:temper==='kind'?0xe8c878:0xd29177}));marker.position.y=2.35;g.add(marker);scene.add(g);g.position.set(x,0,z);return{name,role,temper,obj:g,x,z,met:false}}
+const neighbors=[makeNeighbor('Mara','A river scout',0x697f6c,-7,-7,'kind'),makeNeighbor('Tavi','A careful forager',0x89704d,5,-11,'kind'),makeNeighbor('Rook','A wary trail keeper',0x625e68,-13,4,'wary')];
+// A tiny lived-in riverside camp shows what shelter can become.
+const farCamp=new THREE.Group();scene.add(farCamp);farCamp.position.set(32,0,-13);const fireRing=new THREE.Mesh(new THREE.TorusGeometry(.8,.12,6,12),rockMat);fireRing.rotation.x=Math.PI/2;fireRing.position.y=.14;farCamp.add(fireRing);for(let i=0;i<5;i++){const log=new THREE.Mesh(new THREE.CylinderGeometry(.07,.08,1.5,6),woodMat);log.position.set(1.1,1.1,-.7+i*.36);log.rotation.z=-.66;log.rotation.y=.35;farCamp.add(log)}
+
