const farCamp=new THREE.Group();scene.add(farCamp);farCamp.position.set(32,0,-13);const fireRing=new THREE.Mesh(new THREE.TorusGeometry(.8,.12,6,12),rockMat);fireRing.rotation.x=Math.PI/2;fireRing.position.y=.14;farCamp.add(fireRing);for(let i=0;i<5;i++){const log=new THREE.Mesh(new THREE.CylinderGeometry(.07,.08,1.5,6),woodMat);log.position.set(1.1,1.1,-.7+i*.36);log.rotation.z=-.66;log.rotation.y=.35;farCamp.add(log)}

const state={health:100,hunger:100,thirst:100,berry:0,wood:0,stone:0,fiber:0,day:1,minutes:440,elapsed:0,wall:0,bed:false,fire:false,met:0,won:false,dead:false};
const built=[];const keys={};let running=false,runHeld=false,stick={x:0,y:0},toastTimer=0;
const formatTime=m=>`${String(Math.floor(m/60)%24).padStart(2,'0')}:${String(Math.floor(m)%60).padStart(2,'0')}`;
function announce(text){const t=$('toast');t.textContent=text;t.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('show'),2100)}
function updateInventory(){for(const k of ['berry','wood','stone','fiber']){$(k+'Count').textContent=state[k];$('inv'+k[0].toUpperCase()+k.slice(1)+'s').textContent=state[k]}$('bagCount').textContent=state.berry+state.wood+state.stone+state.fiber}
function updateHUD(){for(const [k,v] of [['health',state.health],['hunger',state.hunger],['thirst',state.thirst]]){$(k+'Bar').style.width=Math.max(0,v)+'%';$(k+'Num').textContent=Math.round(v)}$('dayLabel').textContent='DAY '+String(state.day).padStart(2,'0');$('timeLabel').textContent=formatTime(state.minutes);$('condition').textContent=state.health<35?'Worn down':state.thirst<30?'Parched':state.hunger<30?'Hungry':state.health>90?'Steady':'Tired';$('condition').style.color=state.health<35?'#de8f7c':'#e4c78e';document.querySelector('.survival').classList.toggle('low-health',state.health<25);updateInventory();updateObjective()}
function updateObjective(){let title='Make this place yours',text='Gather what you can before the light leaves the forest.',task=`<span>01</span> &nbsp; Gather supplies`;if(state.wall&&state.bed){title='A place to belong';text='You have made a shelter. Find a neighbor, and see what the forest offers.';task=state.met?'<span>✓</span> &nbsp; Trust is a kind of shelter':'<span>02</span> &nbsp; Meet someone nearby'}else if(state.berry>=3&&state.wood>=2&&state.fiber>=2){title='Ready to make camp';text='You have enough to make shelter. Choose a quiet place near the clearing.';task='<span>02</span> &nbsp; Build a wall and bed'}else if(state.berry>0){title='The forest provides';text='Berries are a start. Find wood and fiber for a place to rest.';task='<span>01</span> &nbsp; Find wood + fiber'}$('objectiveTitle').textContent=title;$('objectiveText').textContent=text;$('taskText').innerHTML=task}
function closestTarget(){let best=null,dist=99;for(const n of nodes){if(!n.active)continue;const d=Math.hypot(player.position.x-n.x,player.position.z-n.z);if(d<dist){best=n;dist=d}}for(const n of neighbors){const d=Math.hypot(player.position.x-n.x,player.position.z-n.z);if(d<dist){best=n;dist=d}}return dist<3.6?best:null}
function nearWater(){return player.position.x>9&&player.position.x<25&&Math.abs(player.position.z)<60}
function updateInteract(){const target=closestTarget(),b=$('interactBtn'),hint=$('hintText');if(!running){b.innerHTML='<span>E</span> Look around';return}if(target?.kind){const names={berry:'Gather berries',wood:'Gather fallen wood',stone:'Gather river stone',fiber:'Gather forest fiber'};b.innerHTML=`<span>E</span> ${names[target.kind]}`;hint.textContent='E / tap to gather'}else if(target?.name){b.innerHTML=`<span>E</span> Speak with ${target.name}`;hint.textContent=target.temper==='kind'?'A neighbor is nearby':'Someone is watching the trail'}else if(nearWater()){b.innerHTML='<span>E</span> Drink fresh water';hint.textContent='The stream is clear and cold'}else{b.innerHTML='<span>E</span> Look around';hint.textContent='WASD to move · E to gather'}}
function interact(){if(!running)return;const t=closestTarget();if(t?.kind){if(!t.active)return;const amount=t.kind==='berry'?2:2;state[t.kind]+=amount;t.active=false;t.obj.visible=false;announce(`+${amount} ${t.kind==='berry'?'wild berries':t.kind==='wood'?'fallen wood':t.kind==='stone'?'river stone':'forest fiber'}`);updateHUD();return}if(t?.name){if(!t.met){t.met=true;state.met++;if(t.temper==='kind'){state.berry+=2;state.thirst=Math.min(100,state.thirst+16);announce(`${t.name}: “Take these. The spring runs clear to the east.” +2 berries`)}else{announce(`${t.name}: “Keep to the old trail, and leave the young trees standing.”`)}updateHUD()}else announce(`${t.name}: “The forest has room for all who care for it.”`);return}if(nearWater()){state.thirst=Math.min(100,state.thirst+42);announce('Cool spring water · thirst restored');updateHUD();return}announce('Nothing close by. Look for berries, branches, and neighbors.')}
$('interactBtn').addEventListener('click',interact);$('mobileGather').addEventListener('click',interact);
function openModal(id){$(id).classList.add('open')}function closeModal(id){$(id).classList.remove('open')}
$('craftBtn').addEventListener('click',()=>openModal('craftModal'));$('bagBtn').addEventListener('click',()=>{updateInventory();openModal('bagModal')});document.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>closeModal(b.dataset.close));
function addWall(){const group=new THREE.Group(),wood=mat(0x896847);for(let i=0;i<4;i++){const plank=new THREE.Mesh(new THREE.BoxGeometry(2.5,.28,.16),wood);plank.position.set(0,.35+i*.34,0);plank.castShadow=true;group.add(plank)}for(const x of [-1.12,1.12]){const post=new THREE.Mesh(new THREE.CylinderGeometry(.12,.14,2.1,6),trunkMat);post.position.set(x,1,0);post.castShadow=true;group.add(post)}group.position.set(player.position.x+2.7,.0,player.position.z);group.rotation.y=-.25;scene.add(group);built.push('Lean-to wall');state.wall++;}
function build(kind){if(kind==='wall'){if(state.wood<3||state.fiber<2)return announce('Need 3 wood and 2 fiber');state.wood-=3;state.fiber-=2;addWall();announce('A wall against the wind. Shelter begins here.')}else if(kind==='bed'){if(state.fiber<4||state.wood<2)return announce('Need 4 fiber and 2 wood');state.fiber-=4;state.wood-=2;const bed=new THREE.Group(),frame=new THREE.Mesh(new THREE.BoxGeometry(1.7,.22,2.6),woodMat);frame.position.y=.25;bed.add(frame);const boughs=new THREE.Mesh(new THREE.BoxGeometry(1.55,.18,2.45),mat(0x77815c));boughs.position.y=.43;bed.add(boughs);for(const x of [-.68,.68])for(const z of [-1,1]){const leg=new THREE.Mesh(new THREE.CylinderGeometry(.09,.1,.4,5),trunkMat);leg.position.set(x,.12,z);bed.add(leg)}bed.position.set(player.position.x,0,player.position.z+1.6);scene.add(bed);built.push('Bed of boughs');state.bed=true;announce('A bed of boughs. Sleep will restore your strength.')}else if(kind==='fire'){if(state.wood<3||state.stone<2)return announce('Need 3 wood and 2 stone');state.wood-=3;state.stone-=2;const g=new THREE.Group();const ring=new THREE.Mesh(new THREE.TorusGeometry(.68,.13,6,12),rockMat);ring.rotation.x=Math.PI/2;ring.position.y=.12;g.add(ring);for(let i=0;i<3;i++){const log=new THREE.Mesh(new THREE.CylinderGeometry(.08,.09,1.2,6),woodMat);log.position.y=.18;log.rotation.x=Math.PI/2;log.rotation.z=i*Math.PI/3;g.add(log)}const flame=new THREE.Mesh(new THREE.ConeGeometry(.25,.75,6),new THREE.MeshBasicMaterial({color:0xff9a4f}));flame.position.y=.58;g.add(flame);g.position.set(player.position.x+1.5,0,player.position.z);scene.add(g);const light=new THREE.PointLight(0xffa45d,2.3,12);light.position.set(g.position.x,2,g.position.z);scene.add(light);built.push('Campfire');state.fire=true;announce('A fire to share warmth.')}else if(kind==='meal'){if(state.berry<3)return announce('Need 3 berries');state.berry-=3;state.hunger=Math.min(100,state.hunger+38);announce('A handful of sweet berries · hunger restored')}else if(kind==='drink'){if(!nearWater())return announce('Find the stream to drink');state.thirst=Math.min(100,state.thirst+42);announce('Cool spring water · thirst restored')}updateHUD()}
document.querySelectorAll('[data-build]').forEach(b=>b.addEventListener('click',()=>build(b.dataset.build)));

